-- Name: micro_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.micro_orders (
    id integer NOT NULL,
    patient_uid uuid NOT NULL,
    admission_id integer,
    ordered_by uuid,
    ordered_by_name character varying(160),
    specimen_type character varying(40) NOT NULL,
    specimen_site character varying(120),
    collected_at timestamp with time zone,
    collected_by uuid,
    test_kind character varying(40) DEFAULT 'culture_sensitivity'::character varying NOT NULL,
    clinical_notes text,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    received_at timestamp with time zone,
    preliminary_at timestamp with time zone,
    finalised_at timestamp with time zone,
    finalised_by uuid,
    finalised_by_name character varying(160),
    growth_status character varying(30),
    comments text,
    tenant_id uuid DEFAULT '00000000-0000-4000-8000-000000000001'::uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT micro_orders_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('collected'::character varying)::text, ('received'::character varying)::text, ('in_progress'::character varying)::text, ('preliminary'::character varying)::text, ('final'::character varying)::text, ('cancelled'::character varying)::text]))),
    CONSTRAINT micro_orders_test_kind_check CHECK (((test_kind)::text = ANY (ARRAY[('culture_sensitivity'::character varying)::text, ('gram_stain'::character varying)::text, ('afb_smear'::character varying)::text, ('afb_culture'::character varying)::text, ('fungal_culture'::character varying)::text, ('mrsa_screen'::character varying)::text, ('esbl_screen'::character varying)::text, ('cre_screen'::character varying)::text, ('kpc_screen'::character varying)::text])))
);

--
-- Name: micro_sensitivities; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.micro_sensitivities (
    id integer NOT NULL,
    isolate_id integer NOT NULL,
    antibiotic_code character varying(40) NOT NULL,
    antibiotic_name character varying(120) NOT NULL,
    result character varying(2) NOT NULL,
    mic_value numeric(8,3),
    mic_unit character varying(20) DEFAULT 'mg/L'::character varying,
    zone_diameter_mm integer,
    method character varying(30),
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT micro_sensitivities_result_check CHECK (((result)::text = ANY (ARRAY[('S'::character varying)::text, ('I'::character varying)::text, ('R'::character varying)::text, ('SDD'::character varying)::text, ('NS'::character varying)::text])))
);

--
-- Name: antibiogram_90d; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.antibiogram_90d AS
 SELECT i.organism_name,
    s.antibiotic_code,
    s.antibiotic_name,
    (count(*))::integer AS total_tested,
    (count(*) FILTER (WHERE ((s.result)::text = 'S'::text)))::integer AS susceptible_count,
    round(((100.0 * (count(*) FILTER (WHERE ((s.result)::text = 'S'::text)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS susceptible_pct,
    o.tenant_id
   FROM ((public.micro_sensitivities s
     JOIN public.micro_isolates i ON ((i.id = s.isolate_id)))
     JOIN public.micro_orders o ON ((o.id = i.order_id)))
  WHERE (o.created_at > (now() - '90 days'::interval))
  GROUP BY i.organism_name, s.antibiotic_code, s.antibiotic_name, o.tenant_id;

