--
-- Name: bi_daily_ops_snapshot; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bi_daily_ops_snapshot AS
 SELECT CURRENT_DATE AS d,
    ( SELECT (count(*))::integer AS count
           FROM public.appointments
          WHERE (appointments.appointment_date = CURRENT_DATE)) AS opd_today,
    ( SELECT (count(*))::integer AS count
           FROM public.appointments
          WHERE ((appointments.appointment_date = CURRENT_DATE) AND ((appointments.status)::text = ANY ((ARRAY['COMPLETED'::character varying, 'CHECKED_OUT'::character varying])::text[])))) AS opd_completed_today,
    ( SELECT (count(*))::integer AS count
           FROM public.admissions
          WHERE ((admissions.status)::text = 'admitted'::text)) AS ip_in_house,
    ( SELECT (count(*))::integer AS count
           FROM public.ot_schedules
          WHERE ((ot_schedules.scheduled_date = CURRENT_DATE) AND ((ot_schedules.status)::text <> 'cancelled'::text))) AS or_cases_today,
    ( SELECT (count(*))::integer AS count
           FROM public.lab_critical_alerts
          WHERE (lab_critical_alerts.acknowledged_at IS NULL)) AS open_critical_alerts,
    ( SELECT COALESCE(sum(billing_payments.amount), (0)::numeric) AS "coalesce"
           FROM public.billing_payments
          WHERE (((billing_payments.collected_at)::date = CURRENT_DATE) AND (billing_payments.reversed = false))) AS collections_today,
    ( SELECT (count(*))::integer AS count
           FROM public.insurance_preauth
          WHERE ((insurance_preauth.status)::text = 'submitted'::text)) AS preauth_pending,
    ( SELECT (count(*))::integer AS count
           FROM public.tpa_claims
          WHERE ((tpa_claims.status)::text = ANY ((ARRAY['submitted'::character varying, 'queried'::character varying])::text[]))) AS claims_outstanding;

--
-- Name: bi_doctor_productivity_30d; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bi_doctor_productivity_30d AS
 SELECT doctor_id,
    doctor_name,
    (count(*))::integer AS opd_appointments_30d,
    (sum(
        CASE
            WHEN ((status)::text = ANY ((ARRAY['COMPLETED'::character varying, 'CHECKED_OUT'::character varying])::text[])) THEN 1
            ELSE 0
        END))::integer AS opd_completed_30d,
    (count(DISTINCT appointment_date))::integer AS days_seen_patients,
    round(((count(*))::numeric / (NULLIF(count(DISTINCT appointment_date), 0))::numeric), 1) AS avg_appointments_per_day
   FROM public.appointments
  WHERE (appointment_date >= (CURRENT_DATE - '30 days'::interval))
  GROUP BY doctor_id, doctor_name;

--
-- Name: bi_ip_occupancy_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bi_ip_occupancy_daily AS
 SELECT (d.d)::date AS d,
    COALESCE(a.ward, 'unassigned'::character varying) AS ward,
    (count(*))::integer AS patients_in_house
   FROM (public.admissions a
     JOIN LATERAL generate_series(((a.created_at)::date)::timestamp with time zone, (COALESCE(((a.created_at + '7 days'::interval))::date, CURRENT_DATE))::timestamp with time zone, '1 day'::interval) d(d) ON (true))
  WHERE ((a.status)::text = 'admitted'::text)
  GROUP BY ((d.d)::date), COALESCE(a.ward, 'unassigned'::character varying);

