--
-- Name: bi_lab_tat_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bi_lab_tat_summary AS
 SELECT (date_trunc('day'::text, received_at))::date AS d,
    (count(*))::integer AS results_received,
    (sum(
        CASE
            WHEN (signed_off_at IS NOT NULL) THEN 1
            ELSE 0
        END))::integer AS results_signed,
    (avg((EXTRACT(epoch FROM (signed_off_at - received_at)) / (60)::numeric)))::integer AS avg_tat_minutes,
    (percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY (((EXTRACT(epoch FROM (signed_off_at - received_at)) / (60)::numeric))::double precision)))::integer AS median_tat_minutes,
    (percentile_cont((0.95)::double precision) WITHIN GROUP (ORDER BY (((EXTRACT(epoch FROM (signed_off_at - received_at)) / (60)::numeric))::double precision)))::integer AS p95_tat_minutes
   FROM public.lab_results
  WHERE (received_at IS NOT NULL)
  GROUP BY ((date_trunc('day'::text, received_at))::date);

--
-- Name: bi_opd_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bi_opd_daily AS
 SELECT appointment_date AS d,
    doctor_id,
    doctor_name,
    (count(*))::integer AS total_appointments,
    (sum(
        CASE
            WHEN ((status)::text = ANY ((ARRAY['COMPLETED'::character varying, 'CHECKED_OUT'::character varying])::text[])) THEN 1
            ELSE 0
        END))::integer AS completed,
    (sum(
        CASE
            WHEN ((status)::text = ANY ((ARRAY['NO_SHOW'::character varying, 'MISSED'::character varying])::text[])) THEN 1
            ELSE 0
        END))::integer AS no_shows,
    (sum(
        CASE
            WHEN ((status)::text = 'CANCELLED'::text) THEN 1
            ELSE 0
        END))::integer AS cancelled,
    round(((100.0 * (sum(
        CASE
            WHEN ((status)::text = ANY ((ARRAY['NO_SHOW'::character varying, 'MISSED'::character varying])::text[])) THEN 1
            ELSE 0
        END))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS no_show_rate_pct
   FROM public.appointments
  GROUP BY appointment_date, doctor_id, doctor_name;

--
-- Name: bi_payer_mix_monthly; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bi_payer_mix_monthly AS
 SELECT (date_trunc('month'::text, created_at))::date AS month,
    claim_type,
    status,
    (count(*))::integer AS claim_count,
    sum(total_billed) AS total_billed,
    sum(claimed_amount) AS total_claimed,
    sum(COALESCE(approved_amount, (0)::numeric)) AS total_approved,
    sum(COALESCE(paid_amount, (0)::numeric)) AS total_paid
   FROM public.tpa_claims c
  GROUP BY ((date_trunc('month'::text, created_at))::date), claim_type, status;

--
