--
-- Name: billing_daily_collection; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_daily_collection AS
 SELECT date((collected_at AT TIME ZONE 'Asia/Kolkata'::text)) AS collection_date,
    shift,
    mode,
    collected_by,
    count(*) AS payment_count,
    sum(
        CASE
            WHEN reversed THEN (0)::numeric
            ELSE amount
        END) AS net_amount,
    sum(amount) AS gross_amount,
    sum(
        CASE
            WHEN reversed THEN amount
            ELSE (0)::numeric
        END) AS reversed_amount,
    tenant_id
   FROM public.billing_payments p
  GROUP BY (date((collected_at AT TIME ZONE 'Asia/Kolkata'::text))), shift, mode, collected_by, tenant_id;

