    approval_status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    raised_by uuid,
    raised_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP,
    approved_by uuid,
    approved_at timestamp(6) with time zone,
    rejected_by uuid,
    rejected_at timestamp(6) with time zone,
    rejection_reason character varying(255),
    paid_at timestamp(6) with time zone,
    paid_by uuid,
    tenant_id uuid DEFAULT '00000000-0000-4000-8000-000000000001'::uuid NOT NULL,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_refund_target CHECK ((((invoice_id IS NOT NULL) AND (advance_id IS NULL)) OR ((invoice_id IS NULL) AND (advance_id IS NOT NULL))))
);

