CREATE TABLE public.bmw_waste_log (
    id integer NOT NULL,
    log_date date DEFAULT CURRENT_DATE NOT NULL,
    log_time time without time zone DEFAULT CURRENT_TIME NOT NULL,
    source_dept character varying(80) NOT NULL,
    source_ward character varying(80),
    destination character varying(40) NOT NULL,
    yellow_kg numeric(8,2) DEFAULT 0 NOT NULL,
    red_kg numeric(8,2) DEFAULT 0 NOT NULL,
    white_kg numeric(8,2) DEFAULT 0 NOT NULL,
    blue_kg numeric(8,2) DEFAULT 0 NOT NULL,
    total_kg numeric(8,2) GENERATED ALWAYS AS ((((yellow_kg + red_kg) + white_kg) + blue_kg)) STORED,
    bag_count integer,
    bag_barcodes text[],
    vehicle_no character varying(40),
    cbwtf_operator character varying(120),
    manifest_no character varying(60),
    weighed_by character varying(120),
    received_by character varying(120),
    photo_keys text[],
    notes text,
    ceiling_exceeded boolean DEFAULT false NOT NULL,
    created_by uuid,
    tenant_id uuid DEFAULT '00000000-0000-4000-8000-000000000001'::uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: bmw_monthly_rollup; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.bmw_monthly_rollup AS
 SELECT tenant_id,
    (date_trunc('month'::text, (log_date)::timestamp with time zone))::date AS month_start,
    (sum(yellow_kg))::numeric(10,2) AS yellow_kg,
    (sum(red_kg))::numeric(10,2) AS red_kg,
    (sum(white_kg))::numeric(10,2) AS white_kg,
    (sum(blue_kg))::numeric(10,2) AS blue_kg,
    (sum(total_kg))::numeric(10,2) AS total_kg,
    (count(*))::integer AS log_entries,
    (count(DISTINCT source_dept))::integer AS departments_logging
   FROM public.bmw_waste_log
  GROUP BY tenant_id, (date_trunc('month'::text, (log_date)::timestamp with time zone));

