    cause_part_2 text,
    icd10_part_2 character varying(10),
    manner_of_death character varying(20) DEFAULT 'natural'::character varying NOT NULL,
    was_pregnancy_related boolean DEFAULT false NOT NULL,
    pregnancy_stage character varying(40),
    was_postsurgery boolean DEFAULT false NOT NULL,
    surgery_within_30d boolean DEFAULT false NOT NULL,
    is_medicolegal boolean DEFAULT false NOT NULL,
