    police_fir_no character varying(60),
    police_clearance_at timestamp with time zone,
    postmortem_required boolean DEFAULT false NOT NULL,
    postmortem_completed_at timestamp with time zone,
    body_released_at timestamp with time zone,
    body_released_to_name character varying(160),
    body_released_to_relation character varying(40),
    body_released_to_id_proof character varying(60),
    body_release_witnessed_by uuid,
    body_release_method character varying(20),
