    tenant_id uuid DEFAULT '00000000-0000-4000-8000-000000000001'::uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT death_records_manner_of_death_check CHECK (((manner_of_death)::text = ANY (ARRAY[('natural'::character varying)::text, ('accident'::character varying)::text, ('suicide'::character varying)::text, ('homicide'::character varying)::text, ('pending'::character varying)::text, ('undetermined'::character varying)::text]))),
    CONSTRAINT death_records_place_of_death_check CHECK (((place_of_death)::text = ANY (ARRAY[('inpatient'::character varying)::text, ('emergency'::character varying)::text, ('icu'::character varying)::text, ('or'::character varying)::text, ('home_brought_dead'::character varying)::text, ('transferred_out_dead'::character varying)::text]))),
    CONSTRAINT death_records_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('certified'::character varying)::text, ('submitted_to_registrar'::character varying)::text, ('registered'::character varying)::text, ('cancelled'::character varying)::text])))
);

