CREATE TABLE public.dialysis_sessions (
    id integer NOT NULL,
    dialysis_patient_id integer NOT NULL,
    vascular_access_id integer,
    session_date date DEFAULT CURRENT_DATE NOT NULL,
    machine_no character varying(40),
    station_no character varying(20),
    modality character varying(20) NOT NULL,
    dialyser character varying(80),
    reuse_count integer,
    scheduled_start_at timestamp with time zone,
    actual_start_at timestamp with time zone,
    actual_end_at timestamp with time zone,
    duration_min integer,
    pre_weight_kg numeric(5,2),
    pre_bp_systolic integer,
    pre_bp_diastolic integer,
    pre_pulse integer,
    pre_temp_c numeric(4,1),
    post_weight_kg numeric(5,2),
    post_bp_systolic integer,
    post_bp_diastolic integer,
    post_pulse integer,
    post_temp_c numeric(4,1),
    prescribed_uf_l numeric(4,2),
    actual_uf_l numeric(4,2),
    anticoag character varying(20),
    anticoag_initial_dose character varying(40),
    anticoag_maintenance character varying(40),
    ktv_calculated numeric(4,2),
    urea_pre_mg_dl integer,
    urea_post_mg_dl integer,
    urr_pct integer,
    intra_dialytic_hypotension boolean DEFAULT false NOT NULL,
    cramps boolean DEFAULT false NOT NULL,
    bleeding boolean DEFAULT false NOT NULL,
    clotting boolean DEFAULT false NOT NULL,
    early_termination boolean DEFAULT false NOT NULL,
    early_termination_reason text,
    status character varying(20) DEFAULT 'scheduled'::character varying NOT NULL,
    conducted_by uuid,
    supervised_by uuid,
    notes text,
    tenant_id uuid DEFAULT '00000000-0000-4000-8000-000000000001'::uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dialysis_sessions_status_check CHECK (((status)::text = ANY (ARRAY[('scheduled'::character varying)::text, ('in_progress'::character varying)::text, ('completed'::character varying)::text, ('cancelled'::character varying)::text, ('no_show'::character varying)::text])))
);

--
-- Name: dialysis_adequacy_30d; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dialysis_adequacy_30d AS
 SELECT tenant_id,
    dialysis_patient_id,
    (count(*))::integer AS sessions_30d,
    (count(ktv_calculated))::integer AS adequacy_measurements,
    round(avg(ktv_calculated), 2) AS mean_ktv,
    round(avg(urr_pct), 1) AS mean_urr_pct,
    (count(*) FILTER (WHERE intra_dialytic_hypotension))::integer AS hypotension_episodes,
    (count(*) FILTER (WHERE early_termination))::integer AS early_terms
   FROM public.dialysis_sessions s
  WHERE ((session_date > (CURRENT_DATE - '30 days'::interval)) AND ((status)::text = 'completed'::text))
  GROUP BY tenant_id, dialysis_patient_id;

