    isolation_required boolean GENERATED ALWAYS AS ((((hbsag_status)::text = 'positive'::text) OR ((hcv_status)::text = 'positive'::text) OR ((hiv_status)::text = 'positive'::text))) STORED,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    notes text,
    tenant_id uuid DEFAULT '00000000-0000-4000-8000-000000000001'::uuid NOT NULL,
