    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dialysis_patients_anticoag_default_check CHECK (((anticoag_default)::text = ANY (ARRAY[('heparin'::character varying)::text, ('lmwh'::character varying)::text, ('citrate'::character varying)::text, ('none'::character varying)::text, ('argatroban'::character varying)::text]))),
    CONSTRAINT dialysis_patients_hbsag_status_check CHECK (((hbsag_status)::text = ANY (ARRAY[('negative'::character varying)::text, ('positive'::character varying)::text, ('pending'::character varying)::text, ('unknown'::character varying)::text]))),
    CONSTRAINT dialysis_patients_hcv_status_check CHECK (((hcv_status)::text = ANY (ARRAY[('negative'::character varying)::text, ('positive'::character varying)::text, ('pending'::character varying)::text, ('unknown'::character varying)::text]))),
