    abandoned_date date,
    abandoned_reason character varying(60),
    last_qa_check_date date,
    qa_flow_ml_min integer,
    last_doppler_date date,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vascular_access_access_type_check CHECK (((access_type)::text = ANY (ARRAY[('avf_radiocephalic'::character varying)::text, ('avf_brachiocephalic'::character varying)::text, ('avf_brachiobasilic'::character varying)::text, ('avg_forearm'::character varying)::text, ('avg_upper_arm'::character varying)::text, ('avg_thigh'::character varying)::text, ('cvc_temporary_ij'::character varying)::text, ('cvc_temporary_femoral'::character varying)::text, ('cvc_tunneled_ij'::character varying)::text, ('cvc_tunneled_subclavian'::character varying)::text, ('pd_catheter'::character varying)::text]))),
    CONSTRAINT vascular_access_side_check CHECK (((side)::text = ANY (ARRAY[('left'::character varying)::text, ('right'::character varying)::text, ('na'::character varying)::text])))
);

--
-- Name: dialysis_today; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dialysis_today AS
 SELECT s.tenant_id,
    s.id AS session_id,
    s.dialysis_patient_id,
    s.station_no,
    s.machine_no,
    s.scheduled_start_at,
    s.actual_start_at,
    s.actual_end_at,
    s.status,
    p.patient_uid,
    p.modality,
    p.isolation_required,
    va.access_type,
    s.intra_dialytic_hypotension,
    s.cramps
   FROM ((public.dialysis_sessions s
     JOIN public.dialysis_patients p ON ((p.id = s.dialysis_patient_id)))
     LEFT JOIN public.vascular_access va ON ((va.id = s.vascular_access_id)))
  WHERE (s.session_date = CURRENT_DATE);

