);

--
-- Name: icu_24h_io_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.icu_24h_io_summary AS
 SELECT icu_admission_id,
    date(recorded_at) AS day,
    sum(COALESCE(iv_fluids_ml, 0)) AS iv_fluids_ml,
    sum(COALESCE(oral_intake_ml, 0)) AS oral_intake_ml,
    sum(COALESCE(blood_products_ml, 0)) AS blood_products_ml,
    sum(COALESCE(urine_output_ml, 0)) AS urine_output_ml,
    sum(COALESCE(drain_output_ml, 0)) AS drain_output_ml,
    sum(COALESCE(ng_aspirate_ml, 0)) AS ng_aspirate_ml,
    sum(COALESCE(net_balance_ml, 0)) AS net_balance_ml,
    (count(*))::integer AS entries_logged
   FROM public.icu_flowsheet_entries
  GROUP BY icu_admission_id, (date(recorded_at));

--
-- Name: icu_admissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.icu_admissions (
    id integer NOT NULL,
    patient_uid uuid NOT NULL,
    admission_id integer,
    unit_code character varying(20) NOT NULL,
    bed_no character varying(20),
    admitted_at timestamp with time zone DEFAULT now() NOT NULL,
    admitting_doctor_uid uuid,
    admitting_doctor_name character varying(160),
    primary_diagnosis text,
    reason_for_icu text,
    apache_ii_score integer,
    apache_ii_at timestamp with time zone,
    sofa_score integer,
    predicted_mortality_pct numeric(4,1),
    expected_los_days integer,
    code_status character varying(20) DEFAULT 'full_code'::character varying,
    code_status_set_at timestamp with time zone,
    code_status_set_by uuid,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    discharged_at timestamp with time zone,
    discharge_disposition character varying(40),
    outcome_notes text,
    tenant_id uuid DEFAULT '00000000-0000-4000-8000-000000000001'::uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    monitoring_interval_minutes integer DEFAULT 60 NOT NULL,
    npo_from timestamp with time zone,
    fasting_until timestamp with time zone,
    pre_op_status character varying(40),
    CONSTRAINT icu_admissions_code_status_check CHECK (((code_status)::text = ANY (ARRAY[('full_code'::character varying)::text, ('dni'::character varying)::text, ('dnr'::character varying)::text, ('dnr_dni'::character varying)::text, ('comfort_only'::character varying)::text]))),
    CONSTRAINT icu_admissions_monitoring_interval_check CHECK ((monitoring_interval_minutes = ANY (ARRAY[5, 10, 15, 30, 60, 120, 240, 480]))),
    CONSTRAINT icu_admissions_status_check CHECK (((status)::text = ANY (ARRAY[('active'::character varying)::text, ('discharged'::character varying)::text, ('transferred'::character varying)::text, ('expired'::character varying)::text])))
);

