--

CREATE TABLE public.icu_daily_bundles (
    id integer NOT NULL,
    icu_admission_id integer NOT NULL,
    bundle_date date DEFAULT CURRENT_DATE NOT NULL,
    a_awakening_done boolean DEFAULT false NOT NULL,
    a_awakening_reason_skipped text,
    b_breathing_done boolean DEFAULT false NOT NULL,
    b_breathing_reason_skipped text,
    b_breathing_outcome character varying(20),
    c_choice_done boolean DEFAULT false NOT NULL,
    c_protocol_followed boolean,
    d_delirium_assessed boolean DEFAULT false NOT NULL,
    d_delirium_positive boolean,
    d_delirium_managed boolean,
    e_mobility_done boolean DEFAULT false NOT NULL,
    e_mobility_level character varying(30),
    e_mobility_reason_skipped text,
    f_family_done boolean DEFAULT false NOT NULL,
    f_family_method character varying(30),
    bundle_complete boolean DEFAULT false NOT NULL,
    bundle_pct integer,
    recorded_by uuid,
    notes text,
    tenant_id uuid DEFAULT '00000000-0000-4000-8000-000000000001'::uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: icu_bundle_30d; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.icu_bundle_30d AS
 SELECT tenant_id,
    bundle_date,
    (count(*))::integer AS patient_days,
    (count(*) FILTER (WHERE bundle_complete))::integer AS complete_days,
    round(((100.0 * (count(*) FILTER (WHERE bundle_complete))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS adherence_pct,
    (count(*) FILTER (WHERE a_awakening_done))::integer AS a_done,
    (count(*) FILTER (WHERE b_breathing_done))::integer AS b_done,
    (count(*) FILTER (WHERE c_choice_done))::integer AS c_done,
    (count(*) FILTER (WHERE d_delirium_assessed))::integer AS d_done,
    (count(*) FILTER (WHERE e_mobility_done))::integer AS e_done,
    (count(*) FILTER (WHERE f_family_done))::integer AS f_done
   FROM public.icu_daily_bundles
  WHERE (bundle_date > (CURRENT_DATE - '30 days'::interval))
  GROUP BY tenant_id, bundle_date
  ORDER BY bundle_date DESC;

