--
-- Name: mortality_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mortality_reviews (
    id integer NOT NULL,
    death_record_id integer NOT NULL,
    review_date date DEFAULT CURRENT_DATE NOT NULL,
    scheduled_for date,
    preventability character varying(20),
    cause_classification character varying(40),
    factor_disease boolean DEFAULT false NOT NULL,
    factor_communication boolean DEFAULT false NOT NULL,
    factor_documentation boolean DEFAULT false NOT NULL,
    factor_diagnostic_delay boolean DEFAULT false NOT NULL,
    factor_treatment_delay boolean DEFAULT false NOT NULL,
    factor_medication boolean DEFAULT false NOT NULL,
    factor_procedural boolean DEFAULT false NOT NULL,
    factor_supervision boolean DEFAULT false NOT NULL,
    factor_resource boolean DEFAULT false NOT NULL,
    factor_handover boolean DEFAULT false NOT NULL,
    discussion_summary text,
    learning_points text,
    action_items text[],
    presented_by uuid,
    presented_by_name character varying(160),
    finalised_by uuid,
    finalised_at timestamp with time zone,
    status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    tenant_id uuid DEFAULT '00000000-0000-4000-8000-000000000001'::uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mortality_reviews_preventability_check CHECK (((preventability)::text = ANY (ARRAY[('not_preventable'::character varying)::text, ('possibly_preventable'::character varying)::text, ('probably_preventable'::character varying)::text, ('definitely_preventable'::character varying)::text]))),
    CONSTRAINT mortality_reviews_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('scheduled'::character varying)::text, ('reviewed'::character varying)::text, ('finalised'::character varying)::text, ('archived'::character varying)::text])))
);

--
-- Name: mortality_30d_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.mortality_30d_summary AS
 SELECT d.tenant_id,
    (count(*))::integer AS total_deaths,
    (count(*) FILTER (WHERE ((d.status)::text = 'registered'::text)))::integer AS registered_count,
    (count(*) FILTER (WHERE d.is_medicolegal))::integer AS medicolegal_count,
    (count(*) FILTER (WHERE d.was_pregnancy_related))::integer AS maternal_deaths,
    (count(*) FILTER (WHERE d.surgery_within_30d))::integer AS surgical_30d_deaths,
    (count(r.id))::integer AS reviews_done,
    (count(r.id) FILTER (WHERE ((r.preventability)::text = ANY ((ARRAY['possibly_preventable'::character varying, 'probably_preventable'::character varying, 'definitely_preventable'::character varying])::text[]))))::integer AS reviews_preventable
   FROM (public.death_records d
     LEFT JOIN public.mortality_reviews r ON ((r.death_record_id = d.id)))
  WHERE (d.date_of_death > (CURRENT_DATE - '30 days'::interval))
  GROUP BY d.tenant_id;

