--
-- Name: or_safety_compliance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.or_safety_compliance AS
SELECT
    NULL::integer AS ot_schedule_id,
    NULL::date AS scheduled_date,
    NULL::character varying(100) AS ot_room,
    NULL::text AS procedure_name,
    NULL::uuid AS surgeon,
    NULL::character varying(50) AS case_status,
    NULL::boolean AS sign_in_complete,
    NULL::boolean AS time_out_complete,
    NULL::boolean AS sign_out_complete,
    NULL::integer AS phases_recorded;

--
-- Name: or_throughput_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.or_throughput_daily AS
 SELECT ot_room,
    scheduled_date,
    (count(*))::integer AS scheduled_cases,
    (sum(
        CASE
            WHEN ((status)::text = 'completed'::text) THEN 1
            ELSE 0
        END))::integer AS completed_cases,
    (sum(
        CASE
            WHEN ((status)::text = 'cancelled'::text) THEN 1
            ELSE 0
        END))::integer AS cancelled_cases,
    (COALESCE(sum(estimated_duration), (0)::bigint))::integer AS estimated_minutes,
    (COALESCE(sum(actual_duration), (0)::bigint))::integer AS actual_minutes,
        CASE
            WHEN (COALESCE(sum(estimated_duration), (0)::bigint) = 0) THEN NULL::numeric
            ELSE round((((COALESCE(sum(actual_duration), (0)::bigint))::numeric / (NULLIF(sum(estimated_duration), 0))::numeric) * (100)::numeric), 1)
        END AS minutes_efficiency_pct
   FROM public.ot_schedules s
  WHERE (ot_room IS NOT NULL)
  GROUP BY ot_room, scheduled_date;

