    tenant_id uuid DEFAULT '00000000-0000-4000-8000-000000000001'::uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pcpndt_form_f_indication_category_check CHECK (((indication_category)::text = ANY (ARRAY[('to_diagnose_intrauterine_pregnancy'::character varying)::text, ('genetic_testing_with_consent'::character varying)::text, ('detection_of_anomalies'::character varying)::text, ('multiple_pregnancy'::character varying)::text, ('placental_localisation'::character varying)::text, ('fetal_well_being'::character varying)::text, ('cervical_incompetence'::character varying)::text, ('placenta_praevia'::character varying)::text, ('other'::character varying)::text]))),
    CONSTRAINT pcpndt_form_f_procedure_kind_check CHECK (((procedure_kind)::text = ANY (ARRAY[('usg'::character varying)::text, ('imaging_other'::character varying)::text, ('invasive'::character varying)::text]))),
    CONSTRAINT pcpndt_form_f_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('completed'::character varying)::text, ('submitted_to_authority'::character varying)::text, ('voided'::character varying)::text])))
);

