--
-- Name: pharmacy_schedule_register_full; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pharmacy_schedule_register_full AS
 SELECT r.id,
    r.tenant_id,
    r.created_at,
    r.schedule_class,
    r.movement_kind,
    i.sku_code,
    i.display_name,
    i.generic_name,
    i.brand_name,
    i.strength,
    i.form,
    b.batch_number,
    b.expiry_date,
    r.quantity,
    r.unit_label,
    r.running_balance,
    r.patient_uid,
    r.prescription_number,
    r.prescriber_name,
    r.prescriber_registration,
    r.patient_id_proof_type,
    r.patient_id_proof_last4,
    r.performed_by_name,
    r.witness_name,
    r.notes
   FROM ((public.pharmacy_schedule_register r
     JOIN public.pharmacy_inventory_items i ON ((i.id = r.inventory_item_id)))
     LEFT JOIN public.pharmacy_inventory_batches b ON ((b.id = r.inventory_batch_id)));

