--
-- Name: tpa_claims_aging; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tpa_claims_aging AS
 SELECT c.id,
    c.claim_number,
    c.patient_uid,
    c.claim_type,
    c.status,
    c.claimed_amount,
    c.approved_amount,
    c.paid_amount,
    c.submitted_at,
    (EXTRACT(epoch FROM (now() - COALESCE(c.submitted_at, c.created_at))) / (86400)::numeric) AS days_since_submit,
        CASE
            WHEN ((c.status)::text = 'paid'::text) THEN 'paid'::text
            WHEN ((c.status)::text = 'denied'::text) THEN 'denied'::text
            WHEN (COALESCE(c.submitted_at, c.created_at) < (now() - '30 days'::interval)) THEN '30+_days_aging'::text
            WHEN (COALESCE(c.submitted_at, c.created_at) < (now() - '15 days'::interval)) THEN '15-30_days_aging'::text
            ELSE 'fresh'::text
        END AS aging_bucket,
    p.policy_number,
    p.payer_id,
    p.tpa_id,
    c.tenant_id
   FROM (public.tpa_claims c
     JOIN public.insurance_policies p ON ((p.id = c.policy_id)));

