--
-- Name: or_safety_compliance _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.or_safety_compliance AS
 SELECT s.id AS ot_schedule_id,
    s.scheduled_date,
    s.ot_room,
    s.procedure_name,
    s.surgeon,
    s.status AS case_status,
    bool_or((((c.phase)::text = 'sign_in'::text) AND ((c.status)::text = 'complete'::text))) AS sign_in_complete,
    bool_or((((c.phase)::text = 'time_out'::text) AND ((c.status)::text = 'complete'::text))) AS time_out_complete,
    bool_or((((c.phase)::text = 'sign_out'::text) AND ((c.status)::text = 'complete'::text))) AS sign_out_complete,
    (count(c.id))::integer AS phases_recorded
   FROM (public.ot_schedules s
     LEFT JOIN public.surgical_safety_checklists c ON ((c.ot_schedule_id = s.id)))
  GROUP BY s.id;

