--

CREATE POLICY clinical_ai_decision_memory_tenant_isolation ON public.clinical_ai_decision_memory USING (((current_setting('app.current_tenant_id'::text, true) IS NULL) OR (current_setting('app.current_tenant_id'::text, true) = ''::text) OR (current_setting('app.current_tenant_id'::text, true) = 'bypass'::text) OR ((tenant_id)::text = current_setting('app.current_tenant_id'::text, true))));

